args.sparql:
SELECT DISTINCT ?mother ?motherLabel WHERE {
  dbr:Gian_Galeazzo_Visconti (dbp:mother|dbo:parent|dbp:parent|dbo:mother) ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
}

SELECT DISTINCT ?maternalGrandmother ?maternalGrandmotherLabel WHERE {
  dbr:Gian_Galeazzo_Visconti dbp:mother ?mother .
  ?mother (dbp:mother|dbo:parent|dbp:parent|dbo:mother) ?maternalGrandmother .
  OPTIONAL { ?maternalGrandmother rdfs:label ?maternalGrandmotherLabel . FILTER(lang(?maternalGrandmotherLabel) = 'en') }
}

SELECT DISTINCT ?maternalGrandmother ?maternalGrandmotherLabel WHERE {
  dbr:Gian_Galeazzo_Visconti dbp:mother ?mother .
  ?mother dbp:mother ?maternalGrandmother .
  OPTIONAL { ?maternalGrandmother rdfs:label ?maternalGrandmotherLabel . FILTER(lang(?maternalGrandmotherLabel) = 'en') }
}

